async function main(){
  let added=0;
  for(const item of rows){
    const existing=await prisma.investigationMaster.findUnique({where:{code:item.code}});
    await prisma.investigationMaster.upsert({
      where:{code:item.code},
      update:{name:item.name,shortName:item.name,category:item.category,department:item.department,specimen:item.specimen,aliases:item.aliases?.join(", "),smsBenchmarkRate:item.smsBenchmarkRate,corporateBenchmarkRate:item.corporateBenchmarkRate,rate:item.rate,pricingLastVerifiedAt:new Date(),active:true},
      create:{code:item.code,name:item.name,shortName:item.name,category:item.category,department:item.department,specimen:item.specimen,aliases:item.aliases?.join(", "),smsBenchmarkRate:item.smsBenchmarkRate,corporateBenchmarkRate:item.corporateBenchmarkRate,rate:item.rate,pricingLastVerifiedAt:new Date(),active:true}
    });
    if(!existing) added++;
  }
  console.log(`Final Investigation Master expansion: ${rows.length} processed, ${added} new entries.`);
}
main().catch(e=>{console.error(e);process.exit(1)}).finally(()=>prisma.$disconnect());
